# ! [stable (feature = "wake_trait" , since = "1.51.0")] # ! [doc = " Types and Traits for working with asynchronous tasks."] # ! [doc = ""] # ! [doc = " **Note**: Some of the types in this module are only available"] # ! [doc = " on platforms that support atomic loads and stores of pointers."] # ! [doc = " This may be detected at compile time using"] # ! [doc = " `#[cfg(target_has_atomic = \"ptr\")]`."] use split_decls_genesis :: ourprelude :: * ; use core :: mem :: ManuallyDrop ; #[cfg (target_has_atomic = "ptr")] use core :: task :: Waker ; use core :: task :: { LocalWaker , RawWaker , RawWakerVTable } ; use crate :: rc :: Rc ; #[cfg (target_has_atomic = "ptr")] use crate :: sync :: Arc ; #[doc = " The implementation of waking a task on an executor."] #[doc = ""] #[doc = " This trait can be used to create a [`Waker`]. An executor can define an"] #[doc = " implementation of this trait, and use that to construct a [`Waker`] to pass"] #[doc = " to the tasks that are executed on that executor."] #[doc = ""] #[doc = " This trait is a memory-safe and ergonomic alternative to constructing a"] #[doc = " [`RawWaker`]. It supports the common executor design in which the data used"] #[doc = " to wake up a task is stored in an [`Arc`]. Some executors (especially"] #[doc = " those for embedded systems) cannot use this API, which is why [`RawWaker`]"] #[doc = " exists as an alternative for those systems."] #[doc = ""] #[doc = " To construct a [`Waker`] from some type `W` implementing this trait,"] #[doc = " wrap it in an [`Arc<W>`](Arc) and call `Waker::from()` on that."] #[doc = " It is also possible to convert to [`RawWaker`] in the same way."] #[doc = ""] #[doc = " <!-- Ideally we'd link to the `From` impl, but rustdoc doesn't generate any page for it within"] #[doc = "      `alloc` because `alloc` neither defines nor re-exports `From` or `Waker`, and we can't"] #[doc = "      link ../../std/task/struct.Waker.html#impl-From%3CArc%3CW,+Global%3E%3E-for-Waker"] #[doc = "      without getting a link-checking error in CI. -->"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " A basic `block_on` function that takes a future and runs it to completion on"] #[doc = " the current thread."] #[doc = ""] #[doc = " **Note:** This example trades correctness for simplicity. In order to prevent"] #[doc = " deadlocks, production-grade implementations will also need to handle"] #[doc = " intermediate calls to `thread::unpark` as well as nested invocations."] #[doc = ""] #[doc = " ```rust"] #[doc = " use std::future::Future;"] #[doc = " use std::sync::Arc;"] #[doc = " use std::task::{Context, Poll, Wake};"] #[doc = " use std::thread::{self, Thread};"] #[doc = " use core::pin::pin;"] #[doc = ""] #[doc = " /// A waker that wakes up the current thread when called."] #[doc = " struct ThreadWaker(Thread);"] #[doc = ""] #[doc = " impl Wake for ThreadWaker {"] #[doc = "     fn wake(self: Arc<Self>) {"] #[doc = "         self.0.unpark();"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " /// Run a future to completion on the current thread."] #[doc = " fn block_on<T>(fut: impl Future<Output = T>) -> T {"] #[doc = "     // Pin the future so it can be polled."] #[doc = "     let mut fut = pin!(fut);"] #[doc = ""] #[doc = "     // Create a new context to be passed to the future."] #[doc = "     let t = thread::current();"] #[doc = "     let waker = Arc::new(ThreadWaker(t)).into();"] #[doc = "     let mut cx = Context::from_waker(&waker);"] #[doc = ""] #[doc = "     // Run the future to completion."] #[doc = "     loop {"] #[doc = "         match fut.as_mut().poll(&mut cx) {"] #[doc = "             Poll::Ready(res) => return res,"] #[doc = "             Poll::Pending => thread::park(),"] #[doc = "         }"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " block_on(async {"] #[doc = "     println!(\"Hi from inside a future!\");"] #[doc = " });"] #[doc = " ```"] #[cfg (target_has_atomic = "ptr")] #[stable (feature = "wake_trait" , since = "1.51.0")] pub trait Wake { #[doc = " Wake this task."] #[stable (feature = "wake_trait" , since = "1.51.0")] fn wake (self : Arc < Self >) ; #[doc = " Wake this task without consuming the waker."] #[doc = ""] #[doc = " If an executor supports a cheaper way to wake without consuming the"] #[doc = " waker, it should override this method. By default, it clones the"] #[doc = " [`Arc`] and calls [`wake`] on the clone."] #[doc = ""] #[doc = " [`wake`]: Wake::wake"] #[stable (feature = "wake_trait" , since = "1.51.0")] fn wake_by_ref (self : & Arc < Self >) { self . clone () . wake () ; } } #[cfg (target_has_atomic = "ptr")] #[stable (feature = "wake_trait" , since = "1.51.0")] impl < W : Wake + Send + Sync + 'static > From < Arc < W > > for Waker { #[doc = " Use a [`Wake`]-able type as a `Waker`."] #[doc = ""] #[doc = " No heap allocations or atomic operations are used for this conversion."] fn from (waker : Arc < W >) -> Waker { unsafe { Waker :: from_raw (raw_waker (waker)) } } } #[cfg (target_has_atomic = "ptr")] #[stable (feature = "wake_trait" , since = "1.51.0")] impl < W : Wake + Send + Sync + 'static > From < Arc < W > > for RawWaker { #[doc = " Use a `Wake`-able type as a `RawWaker`."] #[doc = ""] #[doc = " No heap allocations or atomic operations are used for this conversion."] fn from (waker : Arc < W >) -> RawWaker { raw_waker (waker) } } #[cfg (target_has_atomic = "ptr")] #[inline (always)] fn raw_waker < W : Wake + Send + Sync + 'static > (waker : Arc < W >) -> RawWaker { #[inline (always)] unsafe fn clone_waker < W : Wake + Send + Sync + 'static > (waker : * const ()) -> RawWaker { unsafe { Arc :: increment_strong_count (waker as * const W) } ; RawWaker :: new (waker , & RawWakerVTable :: new (clone_waker :: < W > , wake :: < W > , wake_by_ref :: < W > , drop_waker :: < W >) ,) } unsafe fn wake < W : Wake + Send + Sync + 'static > (waker : * const ()) { let waker = unsafe { Arc :: from_raw (waker as * const W) } ; < W as Wake > :: wake (waker) ; } unsafe fn wake_by_ref < W : Wake + Send + Sync + 'static > (waker : * const ()) { let waker = unsafe { ManuallyDrop :: new (Arc :: from_raw (waker as * const W)) } ; < W as Wake > :: wake_by_ref (& waker) ; } unsafe fn drop_waker < W : Wake + Send + Sync + 'static > (waker : * const ()) { unsafe { Arc :: decrement_strong_count (waker as * const W) } ; } RawWaker :: new (Arc :: into_raw (waker) as * const () , & RawWakerVTable :: new (clone_waker :: < W > , wake :: < W > , wake_by_ref :: < W > , drop_waker :: < W >) ,) } #[doc = " An analogous trait to `Wake` but used to construct a `LocalWaker`."] #[doc = ""] #[doc = " This API works in exactly the same way as `Wake`,"] #[doc = " except that it uses an `Rc` instead of an `Arc`,"] #[doc = " and the result is a `LocalWaker` instead of a `Waker`."] #[doc = ""] #[doc = " The benefits of using `LocalWaker` over `Waker` are that it allows the local waker"] #[doc = " to hold data that does not implement `Send` and `Sync`. Additionally, it saves calls"] #[doc = " to `Arc::clone`, which requires atomic synchronization."] #[doc = ""] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " This is a simplified example of a `spawn` and a `block_on` function. The `spawn` function"] #[doc = " is used to push new tasks onto the run queue, while the block on function will remove them"] #[doc = " and poll them. When a task is woken, it will put itself back on the run queue to be polled"] #[doc = " by the executor."] #[doc = ""] #[doc = " **Note:** This example trades correctness for simplicity. A real world example would interleave"] #[doc = " poll calls with calls to an io reactor to wait for events instead of spinning on a loop."] #[doc = ""] #[doc = " ```rust"] #[doc = " #![feature(local_waker)]"] #[doc = " use std::task::{LocalWake, ContextBuilder, LocalWaker, Waker};"] #[doc = " use std::future::Future;"] #[doc = " use std::pin::Pin;"] #[doc = " use std::rc::Rc;"] #[doc = " use std::cell::RefCell;"] #[doc = " use std::collections::VecDeque;"] #[doc = ""] #[doc = ""] #[doc = " thread_local! {"] #[doc = "     // A queue containing all tasks ready to do progress"] #[doc = "     static RUN_QUEUE: RefCell<VecDeque<Rc<Task>>> = RefCell::default();"] #[doc = " }"] #[doc = ""] #[doc = " type BoxedFuture = Pin<Box<dyn Future<Output = ()>>>;"] #[doc = ""] #[doc = " struct Task(RefCell<BoxedFuture>);"] #[doc = ""] #[doc = " impl LocalWake for Task {"] #[doc = "     fn wake(self: Rc<Self>) {"] #[doc = "         RUN_QUEUE.with_borrow_mut(|queue| {"] #[doc = "             queue.push_back(self)"] #[doc = "         })"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " fn spawn<F>(future: F)"] #[doc = " where"] #[doc = "     F: Future<Output=()> + 'static + Send + Sync"] #[doc = " {"] #[doc = "     let task = RefCell::new(Box::pin(future));"] #[doc = "     RUN_QUEUE.with_borrow_mut(|queue| {"] #[doc = "         queue.push_back(Rc::new(Task(task)));"] #[doc = "     });"] #[doc = " }"] #[doc = ""] #[doc = " fn block_on<F>(future: F)"] #[doc = " where"] #[doc = "     F: Future<Output=()> + 'static + Sync + Send"] #[doc = " {"] #[doc = "     spawn(future);"] #[doc = "     loop {"] #[doc = "         let Some(task) = RUN_QUEUE.with_borrow_mut(|queue| queue.pop_front()) else {"] #[doc = "             // we exit, since there are no more tasks remaining on the queue"] #[doc = "             return;"] #[doc = "         };"] #[doc = ""] #[doc = "         // cast the Rc<Task> into a `LocalWaker`"] #[doc = "         let local_waker: LocalWaker = task.clone().into();"] #[doc = "         // Build the context using `ContextBuilder`"] #[doc = "         let mut cx = ContextBuilder::from_waker(Waker::noop())"] #[doc = "             .local_waker(&local_waker)"] #[doc = "             .build();"] #[doc = ""] #[doc = "         // Poll the task"] #[doc = "         let _ = task.0"] #[doc = "             .borrow_mut()"] #[doc = "             .as_mut()"] #[doc = "             .poll(&mut cx);"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " block_on(async {"] #[doc = "     println!(\"hello world\");"] #[doc = " });"] #[doc = " ```"] #[doc = ""] #[unstable (feature = "local_waker" , issue = "118959")] pub trait LocalWake { #[doc = " Wake this task."] #[unstable (feature = "local_waker" , issue = "118959")] fn wake (self : Rc < Self >) ; #[doc = " Wake this task without consuming the local waker."] #[doc = ""] #[doc = " If an executor supports a cheaper way to wake without consuming the"] #[doc = " waker, it should override this method. By default, it clones the"] #[doc = " [`Rc`] and calls [`wake`] on the clone."] #[doc = ""] #[doc = " [`wake`]: LocalWaker::wake"] #[unstable (feature = "local_waker" , issue = "118959")] fn wake_by_ref (self : & Rc < Self >) { self . clone () . wake () ; } } #[unstable (feature = "local_waker" , issue = "118959")] impl < W : LocalWake + 'static > From < Rc < W > > for LocalWaker { #[doc = " Use a `Wake`-able type as a `LocalWaker`."] #[doc = ""] #[doc = " No heap allocations or atomic operations are used for this conversion."] fn from (waker : Rc < W >) -> LocalWaker { unsafe { LocalWaker :: from_raw (local_raw_waker (waker)) } } } #[allow (ineffective_unstable_trait_impl)] #[unstable (feature = "local_waker" , issue = "118959")] impl < W : LocalWake + 'static > From < Rc < W > > for RawWaker { #[doc = " Use a `Wake`-able type as a `RawWaker`."] #[doc = ""] #[doc = " No heap allocations or atomic operations are used for this conversion."] fn from (waker : Rc < W >) -> RawWaker { local_raw_waker (waker) } } #[inline (always)] fn local_raw_waker < W : LocalWake + 'static > (waker : Rc < W >) -> RawWaker { #[inline (always)] unsafe fn clone_waker < W : LocalWake + 'static > (waker : * const ()) -> RawWaker { unsafe { Rc :: increment_strong_count (waker as * const W) } ; RawWaker :: new (waker , & RawWakerVTable :: new (clone_waker :: < W > , wake :: < W > , wake_by_ref :: < W > , drop_waker :: < W >) ,) } unsafe fn wake < W : LocalWake + 'static > (waker : * const ()) { let waker = unsafe { Rc :: from_raw (waker as * const W) } ; < W as LocalWake > :: wake (waker) ; } unsafe fn wake_by_ref < W : LocalWake + 'static > (waker : * const ()) { let waker = unsafe { ManuallyDrop :: new (Rc :: from_raw (waker as * const W)) } ; < W as LocalWake > :: wake_by_ref (& waker) ; } unsafe fn drop_waker < W : LocalWake + 'static > (waker : * const ()) { unsafe { Rc :: decrement_strong_count (waker as * const W) } ; } RawWaker :: new (Rc :: into_raw (waker) as * const () , & RawWakerVTable :: new (clone_waker :: < W > , wake :: < W > , wake_by_ref :: < W > , drop_waker :: < W >) ,) }